import pandas as pd
import numpy as np

def clean_value(val):
    if pd.isna(val):
        return np.nan
    if isinstance(val, str):
        val = val.replace(',', '.')
    try:
        return float(val)
    except:
        return np.nan

df = pd.read_csv('/root/environment/data/ckd_lab_data.csv')
for col in df.columns:
    if col != 'patient_id':
        df[col] = df[col].apply(clean_value)

df = df.dropna()

stats = df.describe().transpose()
print(stats[['min', 'max', 'mean', '50%']])

